rule sigma 'phishing_credential_harvest' {
  description: 'Phishing credential harvest detected.';
  metadata: {
    author: 'SOC Analyst';
    tags: ['phishing', 'credential_harvest'];
  };
  condition: 
    network.connect from any to any;
  detection:
    - function: network.http;
      condition: http.request.method == 'GET' and http.request.uri.path == '/login'
      and http.request.uri.query =~ 'username=.*&password=.*';
}

